//! Ground-truth files in `test/ground_truth/` (plan P0.0, P0.10). They are generated by the C#
//! reference harness (`mise run reference:expected`) and checked in, so this suite never needs
//! .NET. Every generated text file starts with a provenance header naming the ink commit, the
//! .NET version and the command that regenerates it.

const std = @import("std");
const assert = std.debug.assert;

pub const directory = "test/ground_truth";
pub const file_bytes_max = 4 * 1024 * 1024;

/// The pinned reference: ink v1.2.1 on .NET 8 (plan D17, D19).
pub const header_prefix =
    "# generated by tools/ink_harness from ink v1.2.1 (35c63e52f1d3) on .NET 8.0; " ++
    "regenerate with: mise run reference:";

/// Whether `text` starts with a complete provenance header line.
pub fn has_provenance_header(text: []const u8) bool {
    assert(header_prefix.len > 0);
    if (!std.mem.startsWith(u8, text, header_prefix)) return false;
    const line_end = std.mem.indexOfScalar(u8, text, '\n') orelse return false;
    assert(line_end >= header_prefix.len);
    return line_end > header_prefix.len;
}

test "has_provenance_header accepts the pinned header only" {
    // Goal: the header check itself. Method: a valid header, a different ink commit, and a
    // header with nothing after the command prefix.
    const valid = header_prefix ++ "expected -- smoke\nrest";
    try std.testing.expect(has_provenance_header(valid));
    try std.testing.expect(!has_provenance_header("# generated by someone else\n"));
    try std.testing.expect(!has_provenance_header(header_prefix ++ "\n"));
    try std.testing.expect(!has_provenance_header("text: \"no header\"\n"));
}

test "every generated ground-truth file has a provenance header" {
    // Goal: no checked-in reference data of unknown origin (P0.0). Method: read every
    // .expected and .paths file below test/ground_truth and check its first line.
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var cases = try std.Io.Dir.cwd().openDir(io, directory, .{ .iterate = true });
    defer cases.close(io);
    var walker = try cases.walk(gpa);
    defer walker.deinit();
    var checked: u32 = 0;
    while (try walker.next(io)) |entry| {
        if (entry.kind != .file) continue;
        const generated = std.mem.endsWith(u8, entry.path, ".expected") or
            std.mem.endsWith(u8, entry.path, ".paths");
        if (!generated) continue;
        const text = try cases.readFileAlloc(io, entry.path, gpa, .limited(file_bytes_max));
        defer gpa.free(text);
        if (!has_provenance_header(text)) {
            std.debug.print("missing provenance header: {s}/{s}\n", .{ directory, entry.path });
            return error.MissingProvenance;
        }
        checked += 1;
    }
    // The corpus has well over a hundred cases.
    try std.testing.expect(checked >= 100);
}
